  DataRT_output_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        c77_DataRT_out1_re <= (OTHERS => to_signed(16#00000#, 18));
        c77_DataRT_out1_im <= (OTHERS => to_signed(16#00000#, 18));
      ELSIF enb_1_8280000_1 = '1' THEN
        c77_DataRT_out1_re <= realOutput;
        c77_DataRT_out1_im <= imagOutput;
      END IF;
    END IF;
  END PROCESS DataRT_output_process;


  PipelineRegister1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        c77_DataRT_out1_re_1 <= (OTHERS => to_signed(16#00000#, 18));
        c77_DataRT_out1_im_1 <= (OTHERS => to_signed(16#00000#, 18));
      ELSIF enb_1_8280000_0 = '1' THEN
        c77_DataRT_out1_re_1 <= c77_DataRT_out1_re;
        c77_DataRT_out1_im_1 <= c77_DataRT_out1_im;
      END IF;
    END IF;
  END PROCESS PipelineRegister1_process;


  DataRT_out1_re_gen1: FOR d1 IN 0 TO 47 GENERATE
    DataRT_out1_re_gen: FOR d0 IN 0 TO 47 GENERATE
      DataRT_out1_re(d0, d1) <= c77_DataRT_out1_re_1(d0 + (d1 * 48));
    END GENERATE;
  END GENERATE;

  outputgen2: FOR k IN 0 TO 47 GENERATE
    outputgen3: FOR k1 IN 0 TO 47 GENERATE
      DataSlow_re(k, k1) <= std_logic_vector(DataRT_out1_re(k, k1));
    END GENERATE;
  END GENERATE;

  DataRT_out1_im_gen1: FOR d1 IN 0 TO 47 GENERATE
    DataRT_out1_im_gen: FOR d0 IN 0 TO 47 GENERATE
      DataRT_out1_im(d0, d1) <= c77_DataRT_out1_im_1(d0 + (d1 * 48));
    END GENERATE;
  END GENERATE;

  outputgen: FOR k IN 0 TO 47 GENERATE
    outputgen1: FOR k1 IN 0 TO 47 GENERATE
      DataSlow_im(k, k1) <= std_logic_vector(DataRT_out1_im(k, k1));
    END GENERATE;
  END GENERATE;

  ValidSlow <= ValidRT_out1_1;

END rtl;

